-- Synthetic exact money, actual roles, numbering/snapshots and audit rollback.
begin;
insert into auth.users(id,email) values ('81000000-0000-4000-8000-000000000001','billing-owner@example.invalid'),('81000000-0000-4000-8000-000000000002','billing-member@example.invalid');
insert into public.workspaces(id,name,slug) values ('82000000-0000-4000-8000-000000000001','Billing Synthetic','billing-synthetic'),('82000000-0000-4000-8000-000000000002','Billing Foreign','billing-foreign');
insert into public.workspace_members(workspace_id,user_id,role) values ('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000001','owner'),('82000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000002','member');
insert into public.customers(id,workspace_id,account_kind,legal_name) values ('83000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000001','legal_entity','Billing Synthetic'),('83000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000002','legal_entity','Foreign Synthetic');
create function pg_temp.assert_b(ok boolean) returns void language plpgsql as $$begin if ok is not true then raise exception 'billing assertion';end if;end$$;
create function pg_temp.deny_b(q text,c text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected billing denial %',c;end$$;
create temp table billing_fixture(id uuid,version bigint);
grant all on billing_fixture to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
do $$declare w uuid:='82000000-0000-4000-8000-000000000001';c uuid:='83000000-0000-4000-8000-000000000001';p jsonb;inp jsonb;receipt jsonb;id uuid;other uuid;lines jsonb;issue jsonb;
begin
 p:='{"legal_name":"Synthetic Fiscal","tax_id":"SYNTHETIC-NOT-VALID","address":"Synthetic Road 1","postal_code":"00000","city":"Synthetic","region":"Synthetic","country":"ES"}';
 receipt:=public.billing_v1_issuer_set(w,jsonb_build_object('command_id',gen_random_uuid(),'expected_version',0,'profile',p,'currency','EUR','default_series','A'));
 perform pg_temp.assert_b(receipt->>'version'='1' and receipt->>'status'='profile' and not receipt ? 'tax_id');
 receipt:=public.billing_v1_customer_fiscal_set(w,jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c,'expected_version',0,'profile',p));
 perform pg_temp.assert_b(receipt->>'version'='1');
 lines:='[{"description":"Synthetic Fractional","quantity_milli":1500,"unit_price_minor":101,"discount_bps":500,"tax_bps":2100,"withholding_bps":1500}]';
 inp:=jsonb_build_object('command_id',gen_random_uuid(),'customer_id',c,'issue_on','2026-10-04','due_on','2026-10-10','series','A','currency','EUR','lines',lines);
 receipt:=public.billing_v1_invoice_create_draft(w,inp);id:=(receipt->>'id')::uuid;
 perform pg_temp.assert_b(receipt=public.billing_v1_invoice_create_draft(w,inp));
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_create_draft(%L,%L)',w,(inp||'{"total_minor":999}')::text),'22023');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_create_draft(%L,%L)',w,(inp||jsonb_build_object('command_id',gen_random_uuid(),'customer_id','83000000-0000-4000-8000-000000000002'))::text),'P0002');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_create_draft(%L,%L)',w,(inp||'{"currency":"USD"}')::text),'22023');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_create_draft(%L,%L)',w,(inp||'{"due_on":"2026-10-01"}')::text),'22023');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_create_draft(%L,%L)',w,(inp||'{"lines":[{}]}')::text),'22023');
 issue:=jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',1);
 receipt:=public.billing_v1_invoice_issue(w,issue);
 perform pg_temp.assert_b(receipt->>'status'='issued' and receipt->'number'->>'sequence'='1' and receipt->>'version'='2');
 perform pg_temp.assert_b(receipt=public.billing_v1_invoice_issue(w,issue));
 perform pg_temp.assert_b(public.billing_v1_invoice_get(w,jsonb_build_object('id',id))->'invoice'->'totals'->>'total_minor'='152');
 perform pg_temp.assert_b(not (public.billing_v1_invoice_summary(w,jsonb_build_object('id',id))->'invoice') ? 'issuer');
 perform pg_temp.assert_b(jsonb_array_length(public.billing_v1_invoice_list(w,'{"limit":1}')->'items')=1);
 perform pg_temp.assert_b(public.billing_v1_invoice_financial_summary(w,'{"period":"all"}')->'currencies'->0->>'issued_minor'='152');
 perform pg_temp.assert_b(public.product_v1_dashboard_v2(w,'{"audience":"workspace","period":"all"}')->'financial'->'currencies'->0->>'issued_minor'='152');
 perform pg_temp.assert_b(public.billing_v1_configuration_get(w,jsonb_build_object('customer_id',c))->'customer'->'profile'->>'tax_id'='SYNTHETIC-NOT-VALID');
 perform pg_temp.assert_b(public.billing_v1_invoice_get(w,'{"id":"83000000-0000-4000-8000-000000000002"}') is null);
 perform public.billing_v1_issuer_set(w,jsonb_build_object('command_id',gen_random_uuid(),'expected_version',1,'profile',p||'{"legal_name":"New Synthetic Name"}','currency','EUR','default_series','A'));
 perform pg_temp.assert_b(public.billing_v1_invoice_get(w,jsonb_build_object('id',id))->'invoice'->'issuer'->>'legal_name'='Synthetic Fiscal');

 perform pg_temp.deny_b(format('select public.billing_v1_invoice_issue(%L,%L)',w,(issue||jsonb_build_object('command_id',gen_random_uuid()))::text),'40001');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_update_draft(%L,%L)',w,((inp-'customer_id')||jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',2))::text),'22023');
 perform pg_temp.deny_b(format('select public.billing_v1_invoice_trash(%L,%L)',w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',2)::text),'22023');
 receipt:=public.billing_v1_invoice_mark_paid(w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',2));
 perform pg_temp.assert_b(receipt->>'status'='paid' and receipt->'number'->>'sequence'='1');
 receipt:=public.billing_v1_invoice_reverse_payment(w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',3));
 perform pg_temp.assert_b(receipt->>'status'='issued' and receipt->>'version'='4');
 receipt:=public.billing_v1_invoice_create_draft(w,inp||jsonb_build_object('command_id',gen_random_uuid()));other:=(receipt->>'id')::uuid;
 receipt:=public.billing_v1_invoice_trash(w,jsonb_build_object('command_id',gen_random_uuid(),'id',other,'expected_version',1));
 perform pg_temp.assert_b(receipt->>'status'='trashed');
 receipt:=public.billing_v1_invoice_restore(w,jsonb_build_object('command_id',gen_random_uuid(),'id',other,'expected_version',2));
 perform pg_temp.assert_b(receipt->>'status'='draft');
 insert into billing_fixture values(other,3);
end$$;
reset role;
select pg_temp.assert_b((select total_minor=152 and subtotal_minor=144 and tax_minor=30 and withholding_minor=22 from public.billing_invoices where number_sequence=1 and workspace_id='82000000-0000-4000-8000-000000000001'));
select pg_temp.assert_b((select issuer_snapshot->>'tax_id'='SYNTHETIC-NOT-VALID' from public.billing_invoices where number_sequence=1 and workspace_id='82000000-0000-4000-8000-000000000001'));
select pg_temp.deny_b($q$update public.billing_invoices set total_minor=154 where number_sequence=1$q$,'42501');
select pg_temp.deny_b($q$update public.billing_invoice_lines set description='Tampered' where invoice_id=(select id from public.billing_invoices where number_sequence=1)$q$,'42501');
create function pg_temp.fail_billing_audit() returns trigger language plpgsql as $$begin raise exception 'Synthetic issue cutpoint';end$$;
create trigger billing_test_audit before insert on public.product_audit_events for each row execute function pg_temp.fail_billing_audit();
set local role authenticated;
select pg_temp.deny_b(format('select public.billing_v1_invoice_issue(%L,%L)','82000000-0000-4000-8000-000000000001',jsonb_build_object('command_id',gen_random_uuid(),'id',(select id from billing_fixture),'expected_version',3)::text),'P0001');
reset role;
select pg_temp.assert_b((select next_sequence=2 from public.billing_series where workspace_id='82000000-0000-4000-8000-000000000001'));
select pg_temp.assert_b((select status='draft' and version=3 from public.billing_invoices where id=(select id from billing_fixture)));
drop trigger billing_test_audit on public.product_audit_events;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000002',true);
select pg_temp.deny_b($q$select public.billing_v1_invoice_create_draft('82000000-0000-4000-8000-000000000001','{}')$q$,'42501');
reset role;
update public.workspace_members set status='suspended' where user_id='81000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
select pg_temp.deny_b($q$select public.billing_v1_invoice_issue('82000000-0000-4000-8000-000000000001','{}')$q$,'42501');
reset role;
set local role anon;
select pg_temp.deny_b($q$select public.billing_v1_invoice_issue('82000000-0000-4000-8000-000000000001','{}')$q$,'42501');
reset role;
set local role service_role;
select pg_temp.deny_b($q$select public.billing_v1_invoice_issue('82000000-0000-4000-8000-000000000001','{}')$q$,'42501');
reset role;
rollback;
